    buttonGroup(row, { label: '谁的观测', items: [{ label: '教师（未来 20 帧）', value: 'teacher' }, { label: '学生（当前一帧）', value: 'student' }], value: 'teacher', onPick: function (v) { state.who = v; render(); } });
