      sDim.set(state.who === 'teacher' ? TEACH_DIM + ' 维' : STU_DIM + ' 维', state.who === 'teacher' ? 'warn' : 'good');
      sFut.set(state.who === 'teacher' ? '20 帧（0.02–1.9 s）' : '1 帧（0.02 s）');
