      tb.clear();
      tb.row(['维', '名字', '值'], true);
      var units = ['m', 'rad', 'rad', 'rad', 'm/s', 'm/s', 'm/s', 'rad/s'];
      ROOT_ZH.forEach(function (n, q) { tb.row([String(q + 1), n, sgn(f3(f.mimic[q])) + ' ' + units[q]]); });
      JOINT_ZH.forEach(function (n, q) { tb.row([String(q + 9), n, sgn(f3(f.mimic[8 + q])) + ' rad']); });
